'use strict';
const $=(s,el=document)=>el.querySelector(s);const $$=(s,el=document)=>[...el.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);const pct=n=>Number(n).toFixed(2)+'%';const date=n=>new Date(n*1000).toLocaleString();const id=()=>crypto.randomUUID?crypto.randomUUID():String(Date.now()+Math.random());
const fresh=()=>({balance:100000,initial:100000,dayStart:100000,day:new Date().toISOString().slice(0,10),peak:100000,positions:[],trades:[],journal:[],contacts:[],assets:[],automations:[],alerts:[],rules:{dailyLoss:5,maxLoss:10,target:8,risk:.5,minDays:5},profile:'Custom 100K',completedLessons:[]});
let state=fresh(),user=null,version=null,feed=null,symbol='NQ',page='overview',side='buy',authMode='register',tool='Offer Architect',draftText='',draftMode='',pauseEnds=0,quoteFail=false;
let localOK=true;try{state=JSON.parse(localStorage.getItem('simutrade-guest-v1'))||fresh();}catch{localOK=false;}
const pages={overview:'Overview',trade:'Simulation desk',challenge:'Challenge rules',journal:'Trade journal',quant:'Quant visualizer',coach:'Discipline coach',research:'Research & alerts',studio:'AI cowork studio',crm:'Contacts & pipeline',flows:'Follow-up planner',settings:'Settings & exports'};
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,6000);}
async function api(path,data,headers={}){if(window.SIMUTRADE_PREVIEW)throw Error('Standalone preview. Run the included server for accounts, server saving, and lead capture.');const r=await fetch(path,data===undefined?{headers}:{method:'POST',headers:{'Content-Type':'application/json',...headers},body:JSON.stringify(data)});let d;try{d=await r.json();}catch{throw Error('Server is unavailable. Run the included server to use account and lead features.');}if(!r.ok)throw Error(d.error||'Request failed');return d;}
function persistGuest(){try{localStorage.setItem('simutrade-guest-v1',JSON.stringify(state));}catch{toast('Browser storage is unavailable. Export your work before closing this tab.');}}
async function save(){if(user){try{const r=await api('/api/state',{state,version});state=r.state;version=r.version;}catch(e){await loadAccount();throw e;}}else persistGuest();}
async function loadAccount(){const r=await api('/api/me');user=r.user;version=r.version;if(user)state=r.state;$('#storage-mode').textContent=user?'Account / server saved':'Guest / saved in this browser';$('#account-button').textContent=user?user.name:'Sign in / Save';}
function replay(s='NQ'){let base={NQ:21450,ES:5890,PLTR:64,SPY:590}[s],scale={NQ:8,ES:2,PLTR:.07,SPY:.2}[s],slot=Math.floor(Date.now()/10000);const price=n=>base+scale*(Math.sin(n*.19)*6+Math.sin(n*.071)*10+Math.sin(n*.83)*2);let bars=Array.from({length:64},(_,i)=>{let n=slot-63+i,o=price(n-1),c=price(n);return{o,h:Math.max(o,c)+scale*.9,l:Math.min(o,c)-scale*.8,c,t:n*10};});return {symbol:s,price:Math.round(price(slot)*100)/100,bars,mode:'replay',source:'Synthetic practice feed / 10s bars',timestamp:slot*10,pointValue:s==='NQ'?20:s==='ES'?50:1};}
async function refreshFeed(renderAfter=false){try{feed=await api('/api/market?symbol='+encodeURIComponent(symbol));quoteFail=false;}catch{feed=replay(symbol);quoteFail=true;}if(renderAfter)render();else{updateMarketUI();}checkAlerts();}
function regression(bars){let n=bars.length,ys=bars.map(b=>b.c),sx=n*(n-1)/2,sxx=n*(n-1)*(2*n-1)/6,sy=ys.reduce((a,b)=>a+b,0),sxy=ys.reduce((a,y,i)=>a+y*i,0),slope=(n*sxy-sx*sy)/(n*sxx-sx*sx),intercept=(sy-slope*sx)/n,residuals=ys.map((y,i)=>y-intercept-slope*i),rms=Math.sqrt(residuals.reduce((a,b)=>a+b*b,0)/n);return{slope,intercept,residuals,rms,last:residuals[n-1]};}
function chart(bars,trend=false){if(!bars?.length)return '';let lo=Math.min(...bars.map(x=>x.l)),hi=Math.max(...bars.map(x=>x.h)),pad=(hi-lo)*.2||1;lo-=pad;hi+=pad;const y=v=>235-(v-lo)/(hi-lo)*215,x=i=>18+i*(685/(bars.length-1));const r=regression(bars);let out=[0,1,2,3,4].map(i=>{let v=lo+(hi-lo)*i/4;return `<line class="gridline" x1="0" x2="800" y1="${y(v)}" y2="${y(v)}"/><text x="720" y="${y(v)+4}">${v.toFixed(2)}</text>`;}).join('');out+=bars.map((b,i)=>`<line x1="${x(i)}" x2="${x(i)}" y1="${y(b.h)}" y2="${y(b.l)}" stroke="${b.c>=b.o?'var(--bull)':'var(--bear)'}"/><rect x="${x(i)-2.5}" y="${Math.min(y(b.o),y(b.c))}" width="5" height="${Math.max(1,Math.abs(y(b.o)-y(b.c)))}" fill="${b.c>=b.o?'var(--bull)':'var(--bear)'}"/>`).join('');if(trend)out+=`<path class="trend" d="M${x(0)},${y(r.intercept)} L${x(bars.length-1)},${y(r.intercept+r.slope*(bars.length-1))}"/>`;return `<svg class="chart" viewBox="0 0 800 270" role="img" aria-label="${esc(symbol)} ${feed?.mode==='replay'?'synthetic':'provider'} candlestick series${trend?' with linear trend':''}">${out}<text x="18" y="265">${feed?.mode==='replay'?'Synthetic replay / 10s bars':'Provider / 1min bars'}</text><text x="600" y="265">Simulated funds</text></svg>`;}
function metrics(){const profit=state.balance-state.initial,dayLoss=state.day===new Date().toISOString().slice(0,10)?Math.max(0,state.dayStart-state.balance):0,drawdown=Math.max(0,state.initial-state.balance),wins=state.trades.filter(t=>t.pnl>0).length,days=new Set(state.trades.map(t=>new Date(t.opened*1000).toISOString().slice(0,10))).size,adherence=state.journal.length?state.journal.filter(j=>j.followed).length/state.journal.length*100:null;return{profit,dayLoss,drawdown,wins,days,adherence};}
function metric(label,value,note){return `<div class="metric"><label>${label}</label><strong>${value}</strong><small>${note}</small></div>`;}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function rulesView(){let m=metrics(),r=state.rules;return `<div class="panel-header"><h3>${esc(state.profile)}</h3><span class="pill">Custom practice</span></div>${[['Profit target',Math.max(0,m.profit),state.initial*r.target/100,false],['Daily loss used',m.dayLoss,state.initial*r.dailyLoss/100,true],['Overall loss used',m.drawdown,state.initial*r.maxLoss/100,true]].map(([name,val,max,amber])=>`<div class="rule-row"><div><span class="muted">${name}</span><span class="mono">${money(val)} / ${money(max)}</span></div><div class="track ${amber?'amber':''}"><span style="width:${Math.min(100,val/max*100)}%"></span></div></div>`).join('')}<div class="rule-row"><div><span class="muted">Active trading days</span><span>${m.days} / ${r.minDays}</span></div><div class="progress-ticks">${Array.from({length:r.minDays},(_,i)=>`<i class="${i<m.days?'done':''}"></i>`).join('')}</div></div><a href="#challenge" class="btn small" style="width:100%">Edit practice rules</a><p class="note no-margin">Fixed balance-based limits. Daily boundary: UTC. Unrealized losses and trailing drawdown are not modeled.</p>`;}
function coachData(){let losses=state.trades.slice(0,3).filter(t=>t.pnl<0).length;return losses>=2?{title:'Protect the next decision.',body:'Two or more of your last three trades closed at a loss. Take a five-minute pause, write the setup, and review the risk before entering again.'}:state.positions.length?{title:'Manage the plan you already made.',body:'You have an open simulated position. Review your exit condition before looking for another entry. Moving a stop is a new risk decision.'}:{title:'Your edge starts before entry.',body:'Name the setup. Set the invalidation price. Calculate position size. If you cannot describe all three, observation is today’s trade.'};}
function feedPanel(trend=false){return `<div class="panel-header"><div><h3>${esc(symbol)} <span class="muted">/ ${symbol==='NQ'?'Nasdaq futures practice':symbol==='ES'?'S&P futures practice':'Equity practice'}</span></h3><span class="source-label" id="feed-label">${esc(feed.source)}${quoteFail?' / offline fallback':''}</span></div><div class="bar"><select id="symbol-select" aria-label="Select practice instrument">${['NQ','ES','PLTR','SPY'].map(s=>`<option ${symbol===s?'selected':''}>${s}</option>`).join('')}</select><button type="button" class="small" data-action="refresh">↻ Refresh</button></div></div><div class="big-num mono" id="market-price">${Number(feed.price).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})} <span class="pill">${feed.mode==='replay'?'Synthetic replay':'Provider quotes'}</span></div><div id="market-chart">${chart(feed.bars,trend)}</div>`;}
function tradesTable(){return state.trades.length?`<div class="table-scroll"><table><thead><tr><th>Instrument / time</th><th>Direction</th><th>Entry / exit</th><th>Quantity</th><th>Realized P&L</th><th>Review</th></tr></thead><tbody>${state.trades.slice(0,30).map(t=>`<tr><td>${esc(t.symbol)}<p>${date(t.closed)}</p></td><td>${esc(t.side).toUpperCase()}</td><td class="mono">${t.entry.toFixed(2)} → ${t.exit.toFixed(2)}</td><td>${t.qty}</td><td class="mono ${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</td><td><button type="button" class="small" data-action="review-trade" data-id="${esc(t.id)}">Journal</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>Your first decision starts here.</strong>Close a simulated trade to begin your history.<br><a class="btn small" style="margin-top:18px" href="#trade">Open the simulation desk</a></div>`;}
function overview(){let m=metrics(),c=coachData();return heading(`Welcome to your practice desk${user?', '+esc(user.name.split(' ')[0]):''}.`,'Plan the risk. Rehearse the trade. Keep the lesson.',`<a class="btn small" href="#journal">Open journal</a>`)+`<div class="lab-context-strip"><span>Simulated funds only</span><span>${feed.mode==='replay'?'Synthetic practice feed':'Provider feed · entitlement applies'}</span><span>${user?'Your account workspace':'Guest practice · this browser'}</span></div><div class="lab-journey" aria-label="Your practice loop"><a href="#challenge"><span class="journey-num">01</span><span><b>Define the boundaries</b><small>Set your target, loss limits, and risk cap.</small></span></a><a href="#trade" class="${state.trades.length?'journey-complete':''}"><span class="journey-num">02</span><span><b>Rehearse a trade</b><small>${state.trades.length?state.trades.length+' closed practice trade'+(state.trades.length===1?'':'s'):'Size it, enter, and close it manually.'}</small></span></a><a href="#journal" class="${state.journal.length?'journey-complete':''}"><span class="journey-num">03</span><span><b>Keep the lesson</b><small>${state.journal.length?state.journal.length+' saved reflection'+(state.journal.length===1?'':'s'):'Record the process behind the outcome.'}</small></span></a></div><div class="metric-grid">${metric('Simulated balance',money(state.balance),'Started with '+money(state.initial))}${metric('Realized P&L',`<span class="${m.profit>=0?'positive':'negative'}">${money(m.profit)}</span>`,state.trades.length+' closed practice trade'+(state.trades.length===1?'':'s'))}${metric('Rule adherence',m.adherence===null?'N/A':pct(m.adherence),'Self-reported journal check-ins')}${metric('Risk per trade',pct(state.rules.risk),money(state.balance*state.rules.risk/100)+' maximum planned risk')}</div><div class="dash-grid"><div class="panel">${feedPanel()}<div class="stats-row"><div class="stat"><small>Open positions</small><b>${state.positions.length} / 3</b></div><div class="stat"><small>Closed win rate</small><b>${state.trades.length?pct(m.wins/state.trades.length*100):'N/A'}</b></div><div class="stat"><small>Mode</small><b class="cyan">Practice only</b></div></div></div><div class="panel">${rulesView()}</div></div><div class="two" style="margin-top:22px"><div class="panel"><h3>${c.title}</h3><p class="section-note">The discipline coach</p><p>${c.body}</p><a href="#coach" class="btn small">Take a deliberate pause</a></div><div class="panel"><h3>Learn the loop in four steps.</h3><p class="section-note">Your first focused session</p><ul class="check-list no-margin"><li>Configure your custom challenge rules</li><li>Define risk and enter a simulated position</li><li>Close the position manually</li><li>Journal the quality of your decision</li></ul></div></div><h2>Recent practice trades</h2><div class="panel">${tradesTable()}</div>`;}
function trade(){let p=feed.price,stop=side==='buy'?p-10:p+10,take=side==='buy'?p+20:p-20;return heading('Rehearse the decision.','Every position uses simulated funds. Quotes refresh every 10 seconds while this tab is visible.')+`<div class="dash-grid"><div class="panel">${feedPanel()}<div class="note">Market entries and manual exits only. Stop and target are planning references, not automatic orders. Fees, slippage, margin, and intrabar fills are not modeled.</div></div><div class="panel trade-form"><p class="section-note">New simulated position</p><div class="side-choice"><button type="button" data-side="buy" class="${side==='buy'?'selected':''}">Buy / Long</button><button type="button" data-side="sell" class="${side==='sell'?'selected':''}">Sell / Short</button></div><form id="trade-form"><div class="form-grid"><label>Contracts / shares<input name="qty" id="trade-qty" type="number" value="1" required min="1" max="100" step="1"></label><label>Entry (indicative)<input id="entry-display" value="${p.toFixed(2)}" readonly></label><label>Stop reference<input name="stop" id="trade-stop" type="number" value="${stop.toFixed(2)}" required min="0.01" step="0.01"></label><label>Target reference<input name="take" id="trade-take" type="number" value="${take.toFixed(2)}" required min="0.01" step="0.01"></label></div><div class="risk-readout"><span>Planned risk <b class="mono" id="planned-risk">${money(10*feed.pointValue)}</b></span><span id="reward-ratio" class="cyan">2.00R</span></div><label class="check"><input name="checklist" type="checkbox" required><span>I have named the setup, checked my risk, and accepted the planned loss.</span></label><button class="primary" type="submit" style="width:100%">Place simulated ${side==='buy'?'buy':'sell'}</button><p class="note">Per-trade risk cap: ${money(state.balance*state.rules.risk/100)}. Account: ${esc(state.profile)}.</p></form></div></div><h2>Open simulated positions</h2><div class="panel">${state.positions.length?`<div class="table-scroll"><table><thead><tr><th>Instrument</th><th>Entry / quantity</th><th>Stop / target reference</th><th>Planned risk</th><th>Action</th></tr></thead><tbody>${state.positions.map(p=>`<tr><td>${esc(p.symbol)} <span class="tag">${esc(p.side)}</span></td><td>${p.entry.toFixed(2)} × ${p.qty}</td><td>${p.stop.toFixed(2)} / ${p.take.toFixed(2)}</td><td>${money(p.risk)}</td><td><button type="button" class="small" data-action="close-position" data-id="${esc(p.id)}">Close at current quote</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No open positions. Make your plan before the entry.</div>'}</div><h2>Closed trades</h2><div class="panel">${tradesTable()}</div>`;}
function challenge(){let r=state.rules;return heading('Give your practice boundaries.','Generic custom profiles. Verify real firm requirements before recreating them here.')+`<div class="two"><div class="panel"><h3>Choose your practice conditions.</h3><div class="tabs"><button type="button" data-profile="balanced">Balanced 100K</button><button type="button" data-profile="conservative">Conservative 100K</button></div><form id="rules-form"><label>Profile name<input name="profile" value="${esc(state.profile)}" maxlength="80" required></label><div class="form-grid">${[['target','Profit target %',r.target,.1,100,.1],['dailyLoss','Daily loss limit %',r.dailyLoss,.1,20,.1],['maxLoss','Overall loss limit %',r.maxLoss,.1,50,.1],['risk','Max risk per trade %',r.risk,.01,5,.01],['minDays','Minimum active days',r.minDays,1,100,1]].map(([name,label,val,min,max,step])=>`<label>${label}<input name="${name}" type="number" value="${val}" min="${min}" max="${max}" step="${step}" required></label>`).join('')}</div><button type="submit" class="primary">Save practice rules</button></form></div><div class="panel">${rulesView()}<div class="callout"><strong>Train against the actual rule.</strong><p>This version models fixed overall loss and realized daily loss against initial balance. Daily reset uses UTC. It does not model trailing equity drawdown, payout eligibility, news restrictions, consistency caps, or firm-specific enforcement.</p><p>Risk checks apply at entry; reference stops do not execute automatically.</p></div></div></div>`;}
function journal(){let attach=journal.tradeId||'';return heading('Keep the lesson.','A profitable trade can break the plan. A losing trade can follow it perfectly.',`<button type="button" class="small" data-action="export-journal">Export journal</button>`)+`<div class="two"><div class="panel"><h3>Reflect on the decision.</h3><form id="journal-form"><label>Related trade<select name="tradeId"><option value="">General session reflection</option>${state.trades.map(t=>`<option value="${esc(t.id)}" ${attach===t.id?'selected':''}>${esc(t.symbol)} / ${money(t.pnl)} / ${date(t.closed)}</option>`).join('')}</select></label><div class="form-grid"><label>Setup / title<input name="title" required maxlength="120" placeholder="What was the setup?"></label><label>How did you feel?<select name="emotion"><option>Calm</option><option>Hesitant</option><option>Impatient</option><option>Frustrated</option><option>Overconfident</option></select></label></div><label>What happened, and what will you repeat?<textarea name="note" required maxlength="5000" placeholder="Describe your decision, the rule you followed, and one adjustment for next time."></textarea></label><label class="check"><input name="followed" type="checkbox"><span>I followed my plan, regardless of the outcome.</span></label><button type="submit" class="primary">Save reflection</button></form></div><div class="panel"><div class="panel-header"><h3>Your reflections</h3><span class="pill">${state.journal.length} ${state.journal.length===1?'entry':'entries'}</span></div>${state.journal.length?state.journal.map(j=>`<article class="journal-card"><span class="meta">${date(j.created)} / ${esc(j.emotion)} / ${j.followed?'Plan followed':'Plan needs review'}</span><h3>${esc(j.title)}</h3><p>${esc(j.note)}</p><button type="button" class="small danger" data-action="delete-journal" data-id="${esc(j.id)}">Delete</button></article>`).join(''):'<div class="empty"><strong>No hindsight required.</strong>Start with what you noticed today.</div>'}</div></div>`;}
function quant(){const r=regression(feed.bars);return heading('Turn price into perspective.','Linear regression and residuals calculated from the displayed series. No signal or recommendation.')+`<div class="panel">${feedPanel(true)}<div class="metric-grid" style="margin-top:22px">${metric('Slope / bar',r.slope.toFixed(4),'Least-squares trend')}${metric('Latest residual',r.last.toFixed(4),'Price minus fitted trend')}${metric('Residual RMS',r.rms.toFixed(4),'Root mean squared residual')}${metric('Samples',feed.bars.length,'Visible price observations')}</div><p class="section-note">Residual map / most recent 32 bars</p><div class="heatmap">${r.residuals.slice(-32).map(v=>`<span title="Residual ${v.toFixed(4)}" class="${v>=0?'residual-positive':'residual-negative'}" style="--intensity:${Math.min(.8,.1+Math.abs(v)/(r.rms||1)*.2)}">${v.toFixed(1)}</span>`).join('')}</div><p class="note">Cyan: above fitted trend. Gold: below fitted trend. A residual describes past data; it does not establish a future move. Fit: y = ${r.intercept.toFixed(4)} + ${r.slope.toFixed(4)} × bar index.</p></div><div class="two" style="margin-top:22px"><div class="panel"><h3>Position-size calculator</h3><form id="calculator"><div class="form-grid"><label>Practice balance<input name="balance" type="number" min="1" value="${state.balance}" required></label><label>Risk %<input name="risk" type="number" min=".01" max="100" step=".01" value="${state.rules.risk}" required></label><label>Stop distance (points)<input name="distance" type="number" min=".01" step=".01" value="10" required></label><label>Dollar value per point<input name="point" type="number" min=".01" step=".01" value="${feed.pointValue}" required></label></div><button type="submit" class="primary">Calculate whole units</button></form><div id="calc-output" class="callout">Risk budget ÷ (stop distance × point value), rounded down.</div></div><div class="panel"><h3>Read the shape. Respect the limits.</h3><p>The fitted line describes the average direction of the displayed window. Residuals show where the observed price departs from that line.</p><ul class="check-list"><li>A clean fit is not proof of an edge.</li><li>Changing the window changes the story.</li><li>Backtested or simulated results do not predict live returns.</li></ul><a href="#trade" class="btn small">Bring the math to a practice trade</a></div></div>`;}
const lessons=[['Name the invalidation','Before entering, write the price or condition that makes the setup wrong. Size the position around the loss you accept, rather than around the gain you hope for.'],['Separate outcome from process','Review two questions independently: Did the trade make money? Did you follow your plan? Track both so one does not hide the other.'],['Understand loss geometry','After a 10% decline, returning to the starting balance requires about 11.11% growth. Loss control changes the recovery burden. Practice smaller risk before increasing repetition.'],['Rehearse challenge conditions','Copy only rules you have verified from the provider. Check whether loss is measured from balance or equity, whether it trails, and which timezone governs the day. This app uses simplified fixed balance-based rules.']];
function coach(){let c=coachData();return heading('Keep the trader human.','A transparent rules coach, not a psychological diagnosis or financial adviser.')+`<div class="two"><div class="panel"><h2 style="margin-top:0">${c.title}</h2><p class="section-note">Based on your practice history</p><p>${c.body}</p><div class="callout"><strong>Your pre-trade questions</strong><p>What is the setup?<br>Where is the invalidation?<br>How much can this decision cost?<br>Would I still take it after a five-minute pause?</p></div><a class="btn small" href="#journal" style="margin-top:20px">Write your answer in the journal</a><p class="note">Rules used: open positions prompt a management review; two losses among the last three closed trades prompt a pause. Otherwise, the coach prompts pre-trade planning.</p></div><div class="panel"><p class="section-note">A deliberate pause</p><div class="pause-time" id="pause-time">05:00</div><p style="text-align:center">Step away from the next entry.<br>Return to the reason for this session.</p><div class="bar" style="justify-content:center"><button type="button" class="gold" data-action="pause">Start five-minute pause</button><button type="button" class="small" data-action="cancel-pause">Reset</button></div><p class="note" style="text-align:center">The timer is a voluntary practice tool. It does not lock your account.</p></div></div><h2>Four foundations</h2><div class="panel">${lessons.map(([t,b],i)=>`<details class="lesson"><summary>${i+1}. ${t} ${state.completedLessons.includes(i)?'✓':''}</summary><p>${b}</p><button type="button" class="small" data-action="lesson" data-id="${i}">${state.completedLessons.includes(i)?'Mark unread':'Mark reviewed'}</button></details>`).join('')}</div>`;}
function research(){let r=regression(feed.bars);return heading('Context before conviction.','A practice brief from the current chart window, plus alerts evaluated while the app is open.')+`<div class="two"><div class="panel"><h3>${esc(symbol)} / Practice context</h3><p class="section-note">${esc(feed.source)}</p><p class="mono">Observed price: ${feed.price.toFixed(2)}<br>Window: ${feed.bars.length} bars<br>Trend slope: ${r.slope.toFixed(4)} per bar<br>Latest residual: ${r.last.toFixed(4)}</p><p>The fitted window slopes ${r.slope>=0?'upward':'downward'}, and the latest price sits ${r.last>=0?'above':'below'} that fit. Neither observation establishes a trading signal.</p><div class="callout"><strong>Questions for the next session</strong><p>What would invalidate the setup?<br>Is the planned risk within your challenge allowance?<br>Are you acting from a plan or a recent result?</p></div><p class="note">Not a news feed or a sourced market research report. Provider timestamps and replay labels remain visible in the simulation desk.</p><button type="button" class="small" data-action="download-brief">Download this brief</button></div><div class="panel"><h3>Set an in-app price alert</h3><form id="alert-form"><div class="form-grid"><label>Instrument<select name="symbol">${['NQ','ES','PLTR','SPY'].map(s=>`<option ${symbol===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Condition<select name="direction"><option value="above">At or above</option><option value="below">At or below</option></select></label></div><label>Price threshold<input type="number" name="threshold" step=".01" min=".01" value="${(feed.price+10).toFixed(2)}" required></label><button type="submit" class="primary">Save in-app alert</button></form><p class="note">Only the selected instrument is checked on refresh. Keep the tab open and visible. No background alerts, email, or SMS delivery is configured.</p>${state.alerts.map(a=>`<div class="journal-card"><span class="tag">${a.triggered?'Triggered':'Watching'}</span><p>${esc(a.symbol)} ${esc(a.direction)} ${money(a.threshold)}</p><button type="button" class="small" data-action="delete-alert" data-id="${esc(a.id)}">Remove</button></div>`).join('')}</div></div><h2>Research with evidence</h2><div class="panel"><p>Use the Research Agent to prepare a source checklist before comparing providers. The built-in planner does not retrieve the web or verify current firm rules.</p><a href="#studio" class="btn small">Open research planner</a></div>`;}
const tools=['Offer Architect','Niche Architect','VSL Builder OS','Ads Architect','Category Architect','Sales Asset Architect','Landing Page Copywriter','Research Agent','AI Sales Agent','Nurture Sequence'];
function studio(){return heading('From idea to a working asset.','Editable frameworks included. Gemini generation activates only when a server-side key is connected.')+`<div class="two"><div class="panel"><form id="studio-form"><label>Choose your cowork tool<select name="tool" id="tool-select">${tools.map(t=>`<option ${t===tool?'selected':''}>${t}</option>`).join('')}</select></label><label>Your context / source notes<textarea name="brief" required maxlength="5000" style="min-height:180px" placeholder="Describe your audience, problem, offer, tone, and the next step you want someone to take. Include source material if relevant."></textarea></label><button class="primary" type="submit">Build editable draft</button><p class="note">Guest mode creates a structured planning draft locally. Signed-in mode uses Gemini when configured, otherwise a transparent template. Drafts never publish or send automatically.</p></form><div class="feature"><p class="section-note">One workspace, ten tools</p><p>${tools.map(esc).join(' / ')}</p></div></div><div class="panel"><div class="panel-header"><h3>Working draft</h3><span class="pill" id="draft-mode">${esc(draftMode||'Ready for your brief')}</span></div><div id="draft-output" class="studio-output">${esc(draftText||'Your context belongs here. Add a brief and choose a tool to create the first draft.')}</div><div class="bar"><button type="button" class="small" data-action="save-draft">Save to assets</button><button type="button" class="small" data-action="download-draft">Download draft</button></div></div></div><h2>Saved assets</h2><div class="panel">${state.assets.length?state.assets.map(a=>`<details><summary>${esc(a.title)} <span class="meta">${date(a.created)}</span></summary><p style="white-space:pre-wrap">${esc(a.text)}</p><div class="bar"><button type="button" class="small" data-action="load-draft" data-id="${esc(a.id)}">Load draft</button><button type="button" class="small danger" data-action="delete-asset" data-id="${esc(a.id)}">Delete</button></div></details>`).join(''):'<div class="empty">Save a draft to build your own reusable asset library.</div>'}</div>`;}
function crm(){return heading('Every contact needs a next step.','Your private operator pipeline. No outside CRM or automated messaging is connected.',`<button type="button" class="small" data-action="export-contacts">Export contacts</button>`)+`<div class="panel"><form id="contact-form"><div class="form-grid" style="grid-template-columns:repeat(4,minmax(0,1fr))"><label>Name<input name="name" required maxlength="100"></label><label>Email<input name="email" type="email" required maxlength="254"></label><label>Goal / note<input name="goal" maxlength="500"></label><label>Stage<select name="stage"><option>New</option><option>Qualified</option><option>Conversation</option><option>Active</option></select></label></div><button type="submit" class="primary small">Add contact</button></form></div><div class="kanban" style="margin-top:22px">${['New','Qualified','Conversation','Active'].map(stage=>`<div class="kanban-col"><h3>${stage} / ${state.contacts.filter(c=>c.stage===stage).length}</h3>${state.contacts.filter(c=>c.stage===stage).map(c=>`<div class="contact"><h4>${esc(c.name)}</h4><p>${esc(c.email)}</p><p>${esc(c.goal)}</p><select aria-label="Stage for ${esc(c.name)}" data-contact="${esc(c.id)}">${['New','Qualified','Conversation','Active'].map(s=>`<option ${s===c.stage?'selected':''}>${s}</option>`).join('')}</select><div class="bar" style="margin-top:10px"><button type="button" data-action="contact-followup" data-id="${esc(c.id)}">Plan follow-up</button><button type="button" class="danger" data-action="delete-contact" data-id="${esc(c.id)}">×</button></div></div>`).join('')}</div>`).join('')}</div><div class="panel" style="margin-top:22px"><h3>Landing page requests</h3><p class="note">The configured owner can import server-saved early-access requests into their own pipeline. Other users cannot read this inbox.</p><label>Owner access token<input id="owner-token" type="password" autocomplete="off" placeholder="Token configured on the server"></label><button type="button" class="small" data-action="import-leads">Import owner’s waitlist requests</button></div>`;}
function flows(){return heading('Prepare the next conversation.','A follow-up planning queue. These are unsent drafts; no scheduler or delivery provider is connected.')+`<div class="two"><div class="panel"><h3>Prepare a follow-up</h3><form id="flow-form"><label>Contact<select name="contact" required><option value="">Choose a contact</option>${state.contacts.map(c=>`<option value="${esc(c.id)}" ${flows.contactId===c.id?'selected':''}>${esc(c.name)} / ${esc(c.email)}</option>`).join('')}</select></label><label>Planned date and time<input name="due" type="datetime-local" required></label><label>Draft message<textarea name="message" required maxlength="5000" placeholder="Keep it specific, useful, and connected to their goal."></textarea></label><button type="submit" class="primary">Save unsent follow-up</button></form></div><div class="panel"><h3>Your planned follow-ups</h3>${state.automations.length?state.automations.map(f=>{let c=state.contacts.find(c=>c.id===f.contact);return `<article class="journal-card"><span class="tag">${f.done?'Reviewed':new Date(f.due)<new Date()?'Due for review':'Planned'}</span><h3>${esc(c?.name||'Contact removed')}</h3><span class="meta">${new Date(f.due).toLocaleString()}</span><p>${esc(f.message)}</p><div class="bar"><button type="button" class="small" data-action="complete-flow" data-id="${esc(f.id)}">${f.done?'Reopen':'Mark reviewed'}</button><button type="button" class="small" data-action="download-flow" data-id="${esc(f.id)}">Download draft</button><button type="button" class="small danger" data-action="delete-flow" data-id="${esc(f.id)}">Remove</button></div></article>`;}).join(''):'<div class="empty">Add a contact, then prepare a useful follow-up.</div>'}</div></div>`;}
function settings(){return heading('Your workspace. Your record.','Export your work, review integration status, and manage your practice account.')+`<div class="two"><div class="panel"><h3>Account & data</h3><p>${user?'Signed in as '+esc(user.email)+'. Work is saved on the server.':'Guest practice is saved only in this browser. Create an account for server storage.'}</p><div class="bar">${user?'<button type="button" class="small" data-action="logout">Sign out</button>':'<button type="button" class="primary small" data-action="auth">Create account / Sign in</button>'}<button type="button" class="small" data-action="export-all">Export workspace JSON</button></div><div class="settings-status"><span>Authentication</span><span class="positive">Password + session cookie</span></div><div class="settings-status"><span>Email verification / password recovery</span><span class="gold-text">Not connected</span></div><p class="note">Guest practice is not imported into a new account. Export it before switching if you want to keep a copy. Accounts are not email-verified in this version.</p><div class="callout"><strong>Reset the simulated account</strong><p>Resets the practice balance and clears this workspace’s positions, trade history, journal, contacts, assets, and follow-ups. Export first.</p><button type="button" class="small danger" data-action="reset">Reset this workspace</button></div></div><div class="panel"><h3>Integration status</h3><div id="integration-status"><p class="note">Checking server configuration…</p></div><p class="note">Secrets are server-side environment variables. Never put keys in a downloaded HTML file or browser code. Live instrument coverage and delays depend on your provider entitlement.</p><a href="/privacy.html" class="btn small">Privacy notice</a> <a href="/terms.html" class="btn small">Simulation limits</a></div></div>`;}
function render(){if(!feed)feed=replay(symbol);if(!pages[page])page='overview';$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#breadcrumb').textContent='Workspace / '+pages[page];$('#workspace').innerHTML=({overview,trade,challenge,journal,quant,coach,research,studio,crm,flows,settings}[page])()+`<div class="app-disclaimer">Simulated funds ONLY / ${feed.mode==='replay'?'Synthetic practice data':'Provider data : entitlement and delays apply'} / Education, not financial advice. Reference stops and targets do not auto-execute. Fees and slippage are excluded. <a href="/terms.html">Full simulation limits</a></div>`;if(page==='settings')updateStatus();tickPause();}
async function updateStatus(){try{let h=await api('/api/health');$('#integration-status').innerHTML=[['Storage',h.storage==='firestore'?'Google Firestore':'Local SQLite'],['Market provider',h.market],['Gemini AI generation',h.ai?'Configured':'Not connected / templates available'],['Email / booking / billing','Not connected'],['Outside CRM synchronization','CSV export only']].map(([a,b])=>`<div class="settings-status"><span>${esc(a)}</span><span class="${/Not |only/.test(b)?'gold-text':'positive'}">${esc(b)}</span></div>`).join('');}catch{if($('#integration-status'))$('#integration-status').innerHTML='<p class="note">Offline preview / browser guest mode only. Start the server for accounts, durable leads, and integration status.</p>';}}
function updateMarketUI(){if(page==='quant'){let r=regression(feed.bars),values=$$('.metric strong');if(values.length===4){values[0].textContent=r.slope.toFixed(4);values[1].textContent=r.last.toFixed(4);values[2].textContent=r.rms.toFixed(4);}let heat=$('.heatmap');if(heat)heat.innerHTML=r.residuals.slice(-32).map(v=>`<span title="Residual ${v.toFixed(4)}" class="${v>=0?'residual-positive':'residual-negative'}" style="--intensity:${Math.min(.8,.1+Math.abs(v)/(r.rms||1)*.2)}">${v.toFixed(1)}</span>`).join('');}if($('#market-chart'))$('#market-chart').innerHTML=chart(feed.bars,page==='quant');if($('#market-price'))$('#market-price').innerHTML=Number(feed.price).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+` <span class="pill">${feed.mode==='replay'?'Synthetic replay':'Provider quotes'}</span>`;if($('#feed-label'))$('#feed-label').textContent=feed.source+(quoteFail?' / offline fallback':'');if($('#entry-display'))$('#entry-display').value=feed.price.toFixed(2);updateRisk();}
function updateRisk(){if(!$('#trade-form'))return;let qty=Number($('#trade-qty').value),stop=Number($('#trade-stop').value),take=Number($('#trade-take').value),risk=Math.abs(feed.price-stop)*qty*feed.pointValue,reward=Math.abs(take-feed.price)*qty*feed.pointValue;$('#planned-risk').textContent=money(risk);$('#planned-risk').className=risk>state.balance*state.rules.risk/100?'negative mono':'positive mono';$('#reward-ratio').textContent=risk?(reward/risk).toFixed(2)+'R':':';}
function checkAlerts(){let triggered=state.alerts.filter(a=>!a.triggered&&a.symbol===symbol&&(a.direction==='above'?feed.price>=a.threshold:feed.price<=a.threshold));if(triggered.length){triggered.forEach(a=>a.triggered=Date.now()/1000);save().then(()=>{toast('Practice alert: '+symbol+' reached your threshold.');if(page==='research')render();}).catch(e=>toast(e.message));}}
function download(name,text,type='text/plain'){let u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function csv(rows){return rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
async function guestTrade(d){const r=state.rules;let day=new Date().toISOString().slice(0,10);if(state.day!==day){state.dayStart=state.balance;state.day=day;}let m=metrics();if(m.dayLoss>=state.initial*r.dailyLoss/100||m.drawdown>=state.initial*r.maxLoss/100)throw Error('Challenge loss limit reached. Review or reset your practice.');if(state.positions.length>=3)throw Error('Maximum three open positions.');let p=feed.price,qty=Number(d.qty),stop=Number(d.stop),take=Number(d.take);if(!Number.isInteger(qty)||qty<1||qty>100)throw Error('Use 1-100 whole units.');if(!Number.isFinite(stop)||!Number.isFinite(take)||stop<=0||take<=0||!(side==='buy'?stop<p&&p<take:take<p&&p<stop))throw Error('Stop and target must bracket entry in the trade direction.');let risk=Math.abs(p-stop)*qty*feed.pointValue;if(risk>state.balance*r.risk/100+.01)throw Error('Planned risk exceeds your per-trade cap. Reduce size or stop distance.');let allowance=Math.min(state.initial*r.dailyLoss/100-m.dayLoss,state.initial*r.maxLoss/100-m.drawdown);if(risk+state.positions.reduce((a,p)=>a+p.risk,0)>allowance)throw Error('Combined open risk exceeds remaining loss allowance.');state.positions.push({id:id(),symbol,entry:p,qty,side,stop,take,risk,pointValue:feed.pointValue,opened:Date.now()/1000,mode:feed.mode});persistGuest();}
async function closePosition(pid){if(user){const d=await api('/api/close',{id:pid,version});state=d.state;version=d.version;}else{const p=state.positions.find(p=>p.id===pid);if(!p)throw Error('Position not found');let m;try{m=await api('/api/market?symbol='+p.symbol);}catch{m=replay(p.symbol);}let exit=m.price,pnl=Math.round((exit-p.entry)*(p.side==='buy'?1:-1)*p.qty*p.pointValue*100)/100;state.trades.unshift({...p,exit,pnl,closed:Date.now()/1000});state.positions=state.positions.filter(x=>x.id!==pid);state.balance=Math.round((state.balance+pnl)*100)/100;state.peak=Math.max(state.peak,state.balance);persistGuest();}render();toast('Simulated position closed. Record the decision in your journal.');}
function localDraft(t,b){return `${t.toUpperCase()} / STRUCTURED PLANNING DRAFT\n\nYour brief\n${b}\n\n1. Audience & problem\nIdentify the specific trader or operator, the decision they struggle with, and the context where it happens.\n\n2. Core message\nPractice a repeatable process before increasing exposure. Keep every example tied to simulated funds.\n\n3. Working structure\n${t==='Offer Architect'?'Define the promise, deliverables, delivery hours, support costs, price assumption, and fit criteria.':t==='Research Agent'?'Collect official rule pages, effective dates, instrument specifications, and provider licensing terms. Record claim, URL, date, and verification status. No web retrieval is connected.':t==='Nurture Sequence'||t==='AI Sales Agent'?'Ask about the goal, current obstacle, available practice time, and desired next step. Draft one useful reply and one consent-based follow-up.':t==='VSL Builder OS'?'Open with the decision problem. Demonstrate a simulated risk calculation. Explain the practice loop. End with one clear invitation.':'Write a specific hook, explain the practice problem, demonstrate the workflow, and invite one clear next step.'}\n\n4. Proof & review\nUse only source material you can verify. Do not invent performance, testimonials, profits, or qualification promises.\n\n5. Next action\nReview and edit this framework for your audience. Save it as a working asset; it will not publish or send.\n\nMode: local structured template; AI is not connected in guest mode.`;}
$('#workspace').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=$('button[type=submit]',f)||$('button',f),d=Object.fromEntries(new FormData(f));if(b)b.disabled=true;try{switch(f.id){case'trade-form':await refreshFeed();if(user){let r=await api('/api/trade',{...d,symbol,side,checklist:f.elements.checklist.checked,version});state=r.state;version=r.version;}else await guestTrade(d);toast('Simulated position opened. Your stop and target are references; close the position manually.');break;case'rules-form':state.rules=Object.fromEntries(['dailyLoss','maxLoss','target','risk','minDays'].map(k=>[k,Number(d[k])]));state.profile=d.profile;await save();toast('Practice rules saved.');break;case'journal-form':state.journal.unshift({...d,id:id(),created:Date.now()/1000,followed:f.elements.followed.checked});journal.tradeId='';await save();toast('Reflection saved.');break;case'calculator':{let budget=Number(d.balance)*Number(d.risk)/100,per=Number(d.distance)*Number(d.point),units=Math.floor(budget/per);$('#calc-output').innerHTML=`<strong>${units} whole units</strong><p>Budget: ${money(budget)} / Planned loss at reference stop: ${money(units*per)} / Unused budget: ${money(budget-units*per)}.</p>`;return;}case'alert-form':state.alerts.push({...d,threshold:Number(d.threshold),id:id(),triggered:false});await save();toast('In-app alert saved.');break;case'studio-form':tool=d.tool;if(user){let r=await api('/api/draft',{tool,brief:d.brief,version});draftText=r.text;draftMode=r.mode;}else{draftText=localDraft(tool,d.brief);draftMode='Local template / AI not connected';}$('#draft-output').textContent=draftText;$('#draft-mode').textContent=draftMode;return;case'contact-form':state.contacts.push({...d,id:id(),created:Date.now()/1000});await save();toast('Contact added.');break;case'flow-form':state.automations.push({...d,id:id(),done:false,created:Date.now()/1000});flows.contactId='';await save();toast('Unsent follow-up saved.');break;}render();}catch(err){toast(err.message);}finally{if(b)b.disabled=false;}});
$('#workspace').addEventListener('input',e=>{if(e.target.closest('#trade-form'))updateRisk();});
$('#workspace').addEventListener('change',async e=>{if(e.target.id==='symbol-select'){symbol=e.target.value;await refreshFeed(true);}if(e.target.dataset.contact){try{let c=state.contacts.find(c=>c.id===e.target.dataset.contact);c.stage=e.target.value;await save();render();}catch(err){toast(err.message);}}});
$('#workspace').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.side){side=b.dataset.side;render();return;}if(b.dataset.profile){state.profile=b.dataset.profile==='balanced'?'Balanced 100K':'Conservative 100K';state.rules=b.dataset.profile==='balanced'?{dailyLoss:5,maxLoss:10,target:8,risk:.5,minDays:5}:{dailyLoss:2,maxLoss:5,target:6,risk:.25,minDays:10};try{await save();render();toast('Generic practice profile saved.');}catch(err){toast(err.message);}return;}let a=b.dataset.action,k=b.dataset.id;if(!a)return;b.disabled=true;try{switch(a){case'refresh':await refreshFeed(true);return;case'auth':$('#auth-dialog').showModal();return;case'close-position':await closePosition(k);return;case'review-trade':journal.tradeId=k;location.hash='journal';return;case'delete-journal':if(!confirm('Delete this reflection?'))return;state.journal=state.journal.filter(x=>x.id!==k);await save();break;case'export-journal':download('SimuTrade-Journal.csv',csv([['Date','Title','Emotion','Followed plan','Note'],...state.journal.map(j=>[date(j.created),j.title,j.emotion,j.followed,j.note])]),'text/csv');return;case'delete-alert':state.alerts=state.alerts.filter(x=>x.id!==k);await save();break;case'pause':pauseEnds=Date.now()+300000;tickPause();return;case'cancel-pause':pauseEnds=0;tickPause();return;case'lesson':{let n=Number(k);state.completedLessons=state.completedLessons.includes(n)?state.completedLessons.filter(i=>i!==n):[...state.completedLessons,n];await save();break;}case'save-draft':if(!draftText)throw Error('Create a draft first.');state.assets.unshift({id:id(),title:tool,text:draftText,mode:draftMode,created:Date.now()/1000});await save();toast('Draft saved to assets.');break;case'download-draft':if(!draftText)throw Error('Create a draft first.');download('SimuTrade-Working-Draft.txt',draftText);return;case'load-draft':{let d=state.assets.find(x=>x.id===k);draftText=d.text;draftMode=d.mode;tool=d.title;break;}case'delete-asset':state.assets=state.assets.filter(x=>x.id!==k);await save();break;case'delete-contact':if(!confirm('Remove this contact?'))return;state.contacts=state.contacts.filter(x=>x.id!==k);await save();break;case'contact-followup':flows.contactId=k;location.hash='flows';return;case'export-contacts':download('SimuTrade-Contacts.csv',csv([['Name','Email','Goal','Stage'],...state.contacts.map(c=>[c.name,c.email,c.goal,c.stage])]),'text/csv');return;case'import-leads':{if(!user)throw Error('Sign in as the configured owner to import the waitlist.');let r=await api('/api/leads',undefined,{'X-Owner-Token':$('#owner-token').value}),count=0;for(let l of r.leads){if(!state.contacts.some(c=>c.email===l.email)){state.contacts.push({id:id(),name:l.name,email:l.email,goal:l.goal,stage:'New',created:l.created});count++;}}await save();toast(count+' waitlist contacts imported.');break;}case'complete-flow':{let f=state.automations.find(x=>x.id===k);f.done=!f.done;await save();break;}case'delete-flow':state.automations=state.automations.filter(x=>x.id!==k);await save();break;case'download-flow':download('SimuTrade-Unsent-Follow-Up.txt',state.automations.find(x=>x.id===k).message);return;case'export-all':download('SimuTrade-Workspace.json',JSON.stringify({exportedAt:new Date().toISOString(),mode:user?'account':'guest',state},null,2),'application/json');return;case'logout':await api('/api/logout',{});user=null;try{state=JSON.parse(localStorage.getItem('simutrade-guest-v1'))||fresh();}catch{state=fresh();}await loadAccount();toast('Signed out. Returned to this browser’s guest workspace.');break;case'reset':if(!confirm('Reset this workspace and clear all its saved practice and operator data? Export first if you need a copy.'))return;if(user){let r=await api('/api/reset',{version});state=r.state;version=r.version;}else{state=fresh();persistGuest();}toast('Workspace reset to a new simulated 100K account.');break;case'download-brief':{let r=regression(feed.bars);download('SimuTrade-Practice-Brief.txt',`${symbol} PRACTICE BRIEF\n${feed.source}\nGenerated ${new Date().toISOString()}\nPrice ${feed.price}\nRegression slope ${r.slope}\nLatest residual ${r.last}\nRMS ${r.rms}\nSimulated education only. No forecast or trading recommendation.`);return;}}render();}catch(err){toast(err.message);}finally{b.disabled=false;}});
function tickPause(){if(!$('#pause-time'))return;let secs=pauseEnds?Math.max(0,Math.ceil((pauseEnds-Date.now())/1000)):300;$('#pause-time').textContent=String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0');if(pauseEnds&&secs===0){pauseEnds=0;toast('Pause complete. Review your plan before the next entry.');}}
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>{if(location.hash.slice(1)===b.dataset.page)render();else location.hash=b.dataset.page;$('#sidebar').classList.remove('open');$('#app-menu').setAttribute('aria-expanded','false');}));
window.addEventListener('hashchange',()=>{if(location.hash==='#workspace'){$('#workspace').focus();return;}page=location.hash.slice(1)||'overview';render();window.scrollTo(0,0);});
$('#app-menu').addEventListener('click',()=>{let open=$('#sidebar').classList.toggle('open');$('#app-menu').setAttribute('aria-expanded',String(open));});
$('#workspace').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#app-menu').setAttribute('aria-expanded','false');});
$('#account-button').addEventListener('click',()=>{if(user)location.hash='settings';else $('#auth-dialog').showModal();});$('#close-auth').addEventListener('click',()=>$('#auth-dialog').close());
$$('[data-auth]').forEach(b=>b.addEventListener('click',()=>{authMode=b.dataset.auth;$$('[data-auth]').forEach(x=>x.classList.toggle('selected',x===b));$('#name-label').hidden=authMode==='login';$('#auth-form button[type=submit]').textContent=authMode==='login'?'Sign in':'Create account';$('#auth-form input[name=password]').autocomplete=authMode==='login'?'current-password':'new-password';$('#auth-status').textContent='';}));
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();let f=e.target,b=$('button[type=submit]',f);b.disabled=true;$('#auth-status').textContent='Connecting…';try{await api('/api/'+authMode,Object.fromEntries(new FormData(f)));await loadAccount();$('#auth-dialog').close();f.reset();render();toast('Account opened. This workspace is saved on the server.');}catch(err){$('#auth-status').textContent=err.message;}finally{b.disabled=false;}});
(async()=>{try{await loadAccount();}catch{}page=location.hash.slice(1)||window.SIMUTRADE_START_PAGE||'overview';await refreshFeed();render();if(!localOK)toast('Browser storage could not be loaded. Export your work before closing.');})();setInterval(()=>{if(!document.hidden)refreshFeed();},10000);setInterval(tickPause,1000);
